#include <stdlib.h>
#include <string.h>

#define MAX_TARGET_LEN 15
#define ALPHABET_SIZE 26

// Hash map for memoization: key is a string representing the remaining target,
// value is the minimum stickers needed.
// We'll implement a simple hashmap with chaining for memoization.

typedef struct MemoNode {
    char *key;
    int val;
    struct MemoNode *next;
} MemoNode;

#define MEMO_SIZE 10007

static MemoNode *memo[MEMO_SIZE];

static unsigned int hash_str(const char *s) {
    unsigned int h = 0;
    while (*s) {
        h = h * 131 + (*s++);
    }
    return h % MEMO_SIZE;
}

static int memo_get(const char *key) {
    unsigned int h = hash_str(key);
    MemoNode *cur = memo[h];
    while (cur) {
        if (strcmp(cur->key, key) == 0) return cur->val;
        cur = cur->next;
    }
    return -2; // not found
}

static void memo_put(const char *key, int val) {
    unsigned int h = hash_str(key);
    MemoNode *cur = memo[h];
    while (cur) {
        if (strcmp(cur->key, key) == 0) {
            cur->val = val;
            return;
        }
        cur = cur->next;
    }
    // insert new
    MemoNode *node = (MemoNode *)malloc(sizeof(MemoNode));
    node->key = strdup(key);
    node->val = val;
    node->next = memo[h];
    memo[h] = node;
}

static void memo_free() {
    for (int i = 0; i < MEMO_SIZE; i++) {
        MemoNode *cur = memo[i];
        while (cur) {
            MemoNode *tmp = cur;
            cur = cur->next;
            free(tmp->key);
            free(tmp);
        }
        memo[i] = NULL;
    }
}

static int min(int a, int b) {
    return a < b ? a : b;
}

static int dfs(int **stickersCount, int stickersSize, char *target) {
    if (*target == '\0') return 0;
    int memoVal = memo_get(target);
    if (memoVal != -2) return memoVal;

    int targetCount[ALPHABET_SIZE] = {0};
    for (char *p = target; *p; p++) {
        targetCount[*p - 'a']++;
    }

    int ans = -1;

    for (int i = 0; i < stickersSize; i++) {
        // Optimization: skip stickers that don't contain the first char of target
        if (stickersCount[i][target[0] - 'a'] == 0) continue;

        // Construct new target after using one sticker i
        char newTarget[MAX_TARGET_LEN + 1];
        int pos = 0;
        for (int c = 0; c < ALPHABET_SIZE; c++) {
            int remain = targetCount[c] - stickersCount[i][c];
            if (remain > 0) {
                for (int k = 0; k < remain; k++) {
                    newTarget[pos++] = 'a' + c;
                }
            }
        }
        newTarget[pos] = '\0';

        int tmp = dfs(stickersCount, stickersSize, newTarget);
        if (tmp != -1) {
            if (ans == -1) ans = tmp + 1;
            else ans = min(ans, tmp + 1);
        }
    }

    memo_put(target, ans);
    return ans;
}

int minStickers(char **stickers, int stickersSize, char *target) {
    // Clear memo
    memo_free();

    // Precompute count of letters in each sticker
    int **stickersCount = (int **)malloc(sizeof(int *) * stickersSize);
    for (int i = 0; i < stickersSize; i++) {
        stickersCount[i] = (int *)calloc(ALPHABET_SIZE, sizeof(int));
        for (char *p = stickers[i]; *p; p++) {
            if (*p >= 'a' && *p <= 'z')
                stickersCount[i][*p - 'a']++;
        }
    }

    int res = dfs(stickersCount, stickersSize, target);

    for (int i = 0; i < stickersSize; i++) {
        free(stickersCount[i]);
    }
    free(stickersCount);
    memo_free();

    return res;
}

